const IMG = {
  logo: 'data:image/jpeg;base64,',
  hero: 'data:image/jpeg;base64,',
  price: 'data:image/jpeg;base64,',
  blackbouquet: 'data:image/jpeg;base64,',
  pinkbouquet: 'data:image/jpeg;base64,',
  gift: 'data:image/jpeg;base64,',
  flower: 'data:image/jpeg;base64,'
};

const products = [["Pastel Bloom Bouquet", "A soft pink & lavender bouquet for sweet surprises.", "₹799", "hero"], ["Classic Rose Bouquet", "A forever rose-style handmade bouquet.", "₹699", "blackbouquet"], ["Pretty Pink Bouquet", "A cheerful pink bouquet for birthdays & special days.", "₹749", "pinkbouquet"], ["Custom Gift Bouquet", "Add colours, notes and your own little idea.", "₹899", "gift"], ["Mini Flower Set", "Cute handmade blooms for small celebrations.", "₹499", "flower"]];

const $ = (s) => document.querySelector(s);
const $$ = (s) => document.querySelectorAll(s);

$("#brandLogo").src = IMG.logo;
$("#heroImage").src = IMG.hero;
$("#storyImage").src = IMG.hero;

$("#products").innerHTML = products.map(p => `
  <article class="product">
    <div class="product-img"><img src="${IMG[p[3]]}" alt="${p[0]}" loading="lazy"></div>
    <div class="product-info">
      <span class="tag">HANDMADE • CUSTOMIZABLE</span>
      <h3>${p[0]}</h3>
      <p>${p[1]}</p>
      <div class="price"><b>${p[2]}</b><button data-order="${p[0]}">Enquire →</button></div>
    </div>
  </article>`).join("");

function showPage(id){
  $$(".page").forEach(p => p.classList.toggle("active", p.id === id));
  $("#nav").classList.remove("open");
  window.scrollTo({top:0,behavior:"smooth"});
}
function route(){
  const id = location.hash.replace("#","") || "home";
  showPage(document.getElementById(id) ? id : "home");
}
window.addEventListener("hashchange", route);
route();

$$("[data-page]").forEach(el => el.addEventListener("click", e => {
  const id = el.dataset.page;
  if(id){ e.preventDefault(); location.hash = id; }
}));

$("#menuBtn").addEventListener("click",()=>$("#nav").classList.toggle("open"));

function toast(text){
  const t=$("#toast"); t.textContent=text; t.classList.add("show");
  setTimeout(()=>t.classList.remove("show"),2600);
}
$$("[data-order]").forEach(btn => btn.addEventListener("click",()=>{
  $("#type").value = btn.dataset.order;
  location.hash="order";
  setTimeout(()=>$("#name").focus(),350);
}));

$("#orderForm").addEventListener("submit",e=>{
  e.preventDefault();
  const name=$("#name").value.trim();
  const type=$("#type").value;
  const colour=$("#colour").value.trim() || "Any colour";
  const message=$("#message").value.trim() || "No extra message";
  const text = `Hi Muksina Handmade!%0A%0AName: ${encodeURIComponent(name)}%0AOrder: ${encodeURIComponent(type)}%0AColour: ${encodeURIComponent(colour)}%0AMessage: ${encodeURIComponent(message)}`;
  window.open(`https://wa.me/?text=${text}`,"_blank");
  toast("WhatsApp enquiry prepared ✿");
});
